import{_ as d,o as c,c as o,a3 as t}from"./chunks/framework.DAK02U1-.js";const h=JSON.parse('{"title":"xclang 命令","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"xclang 命令 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/reference/xclang-command"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/reference/xclang-command"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/xclang-command"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/xclang-command"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/xclang-command"}]]},"headers":[],"relativePath":"zh/xclang/reference/xclang-command.md","filePath":"zh/xclang/reference/xclang-command.md","lastUpdated":1794509097000}'),a={name:"zh/xclang/reference/xclang-command.md"};function s(n,e,r,l,i,g){return c(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="xclang-命令" tabindex="-1">xclang 命令 <a class="header-anchor" href="#xclang-命令" aria-label="Permalink to &quot;xclang 命令&quot;">​</a></h1><p><code>xclang</code> 用于获取工具链未内置且不允许二次分发的厂商 SDK，并在运行 cargo 时将当前工具链设为各目标平台的 C 编译器与链接器。每个工具链压缩包都内置了这个命令，位于 <code>bin/xclang</code>（在 Windows 上为 <code>xclang.exe</code>）。SDK 为什么由用户自行获取而不随包分发，见<a href="./../guide/cross-compiling">交叉编译</a>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xclang sdk list [macos|windows]</span></span>
<span class="line"><span>xclang sdk fetch macos --accept-license [--preset P] [--version V]</span></span>
<span class="line"><span>xclang sdk fetch windows --accept-license [--preset P] [--msvc-version V] [--sdk-version V] [--arch x86_64,aarch64,x86]</span></span>
<span class="line"><span>xclang sdk path macos|windows [the selection options of fetch]</span></span>
<span class="line"><span>xclang sdk packages macos|windows [the selection options of fetch] [--json]</span></span>
<span class="line"><span>xclang sdk use &lt;name&gt;</span></span>
<span class="line"><span>xclang sdk remove &lt;name&gt;</span></span>
<span class="line"><span>xclang target list</span></span>
<span class="line"><span>xclang target add &lt;target&gt;...</span></span>
<span class="line"><span>xclang target remove &lt;target&gt;...</span></span>
<span class="line"><span>xclang cargo &lt;cargo&#39;s arguments&gt;</span></span>
<span class="line"><span>xclang --version</span></span></code></pre></div><h2 id="厂商-sdk" tabindex="-1">厂商 SDK <a class="header-anchor" href="#厂商-sdk" aria-label="Permalink to &quot;厂商 SDK&quot;">​</a></h2><p><code>xclang sdk fetch</code> 直接从厂商下载 SDK。为应对偶发的下载中断或文件损坏，每次下载最多重试三次，并对照版本表中锁定的文件大小与 sha256 摘要校验。如果某个 macOS SDK 所在的安装包已被 Apple 下架，它会在 Apple 软件更新目录列出的其他安装包中寻找对应版本，并校验 SDK 的内容摘要（<a href="./../design/macos#packages-apple-withdraws-and-content-digests">原因见此</a>）。校验通过后，它会将 SDK 解压到独立目录中：</p><table tabindex="0"><thead><tr><th>SDK</th><th>目录</th><th>用途</th></tr></thead><tbody><tr><td>macOS</td><td><code>$XCLANG/sdk/macos-&lt;version&gt;</code></td><td>在 Linux 与 Windows 主机上运行 <code>clang++ --target=arm64-apple-macos</code>（<a href="./../guide/cross-compiling#on-linux-and-windows-hosts">macOS</a>）；在 macOS 主机上或使用工具链外部的 SDK 时，需传入 <code>-isysroot &lt;dir&gt;</code></td></tr><tr><td>MSVC 与 Windows SDK</td><td><code>$XCLANG/sdk/windows-msvc&lt;version&gt;-sdk&lt;version&gt;</code></td><td><code>clang++ --target=x86_64-pc-windows-msvc</code>、<code>clang-cl</code>：<a href="./../guide/cross-compiling#msvc-targets">MSVC 目标平台</a></td></tr></tbody></table><table tabindex="0"><thead><tr><th>命令或选项</th><th></th></tr></thead><tbody><tr><td><code>--accept-license</code></td><td>未传入时，fetch 会打印厂商的许可条款并停止</td></tr><tr><td><code>sdk path</code></td><td>打印在给定相同选择选项（<code>--preset</code>、<code>--version</code>、<code>--msvc-version</code>、<code>--sdk-version</code>、<code>--arch</code>）时 fetch 解压的目标目录，例如 <code>-isysroot &quot;$(xclang sdk path macos)&quot;</code>。传入 <code>--arch</code> 时，如果目录中的 SDK 缺少所列的任一架构，命令会报错失败</td></tr><tr><td><code>sdk packages</code></td><td>打印在给定相同选择选项时，fetch 为尚未获取的 SDK 所需下载的安装包：列出每个安装包的 sha256、文件大小和 URL，或配合 <code>--json</code> 输出 <code>{&quot;name&quot;: &lt;the SDK&#39;s directory&gt;, &quot;packages&quot;: [{&quot;url&quot;, &quot;size&quot;, &quot;sha256&quot;, &quot;file&quot;}]}</code>。构建系统可自行将这些安装包按 <code>file</code> 字段的文件名下载到某个目录中，再交由 <code>fetch --cache</code> 从中读取；Bazel 模块正是这样做的（<a href="./../integrations/bazel#build-for-msvc-and-for-macos-anywhere">Bazel</a>）。对于构建系统无法自行下载的安装包——例如已被 Apple 下架的安装包，或没有锁定 sha256 的安装包（超出版本表的 <code>--version latest</code>）——仍由 fetch 自行下载</td></tr><tr><td><code>--cache &lt;dir&gt;</code></td><td>fetch 将下载的文件保存在此目录中，并按 sha256 直接复用目录中已有的文件</td></tr><tr><td><code>sdk list</code></td><td>列出 xclang 支持的预设与版本（标明默认项）、已下载的 SDK 以及当前启用的 SDK；解压最后一步写出的 <code>.xclang-sdk.json</code> 记录了 SDK 的来源信息，缺少此文件的目录会被列为未完成</td></tr><tr><td><code>sdk use &lt;name&gt;</code></td><td>将某个已下载的 SDK 设为当前启用的版本（见下文）</td></tr><tr><td><code>sdk remove &lt;name&gt;</code></td><td>删除已下载的 SDK；若它是当前启用的版本，还会一并删除指向它的链接</td></tr><tr><td><code>--preset &lt;image&gt;</code></td><td>使用对应 GitHub runner 镜像或标签（如 <code>windows-2022</code>、<code>macos-15</code>）的 SDK 版本；默认分别为 <code>windows-latest</code> 与 <code>macos-latest</code></td></tr><tr><td><code>--version</code>, <code>--sdk-version</code>, <code>--msvc-version</code></td><td>指定完整或部分版本号（如 <code>15</code>、<code>10.0.26100</code>、<code>14.44</code>）以替代预设版本，匹配时选取最新的对应版本。<code>--version latest</code> 会选取当前 Apple 更新目录中列出的最新 macOS SDK，它可能超出版本表范围，且不具备可复现性</td></tr><tr><td><code>--arch &lt;archs&gt;</code></td><td>要下载的 Windows SDK 架构，可选 <code>x86_64</code>、<code>aarch64</code> 与 <code>x86</code>，默认为 <code>x86_64,aarch64</code>。再次下载同一 SDK 时会保留已有的架构，例如传入 <code>--arch x86</code> 会追加 x86 架构</td></tr><tr><td><code>--sdk-dir &lt;dir&gt;</code></td><td>存放 SDK 的其他目录，适用于工具链安装在只读目录中的场景</td></tr><tr><td><code>--links &lt;how&gt;</code></td><td>fetch 创建 macOS SDK 内链接的方式：<code>junction</code> 使用目录联接与硬链接（Windows 默认）；<code>symlink</code> 使用符号链接（其他系统默认）；或 <code>copy</code> 直接拷贝文件</td></tr><tr><td><code>--root &lt;dir&gt;</code></td><td>命令所操作的工具链目录，默认为命令自身所在的工具链</td></tr></tbody></table><p>重新下载已存在的 SDK 时，会先将旧目录暂存为 <code>.&lt;name&gt;.old</code>，再重新解压，直到新目录完整就绪后才清理旧目录。如果下载或解压失败，会将旧目录恢复原位，保持可用；如果过程被中断，则留待下次执行时恢复。在此期间，磁盘需要留有同时容纳新旧两个 SDK 的空间。如果旧目录无法移开（例如在 Windows 上有程序正打开其中的文件），下载会立即停止，原有 SDK 保持不变。</p><h3 id="当前启用的-sdk" tabindex="-1">当前启用的 SDK <a class="header-anchor" href="#当前启用的-sdk" aria-label="Permalink to &quot;当前启用的 SDK&quot;">​</a></h3><p>最后一次下载的 SDK 或由 <code>sdk use</code> 指定的 SDK 即为当前启用的版本：<code>$XCLANG/sdk/windows</code> 与 <code>$XCLANG/sdk/macos</code> 会通过符号链接（在 Windows 上则是无需提权的目录联接）指向它，从而为配置文件提供固定路径。每个 Windows SDK 都按已下载的架构和驱动模式包含对应的配置文件 <code>&lt;arch&gt;-pc-windows-msvc.cfg</code> 与 <code>&lt;arch&gt;-pc-windows-msvc-clang-cl.cfg</code>，其中记录了 SDK 路径及具体版本号。MSVC 目标平台自身的配置文件会通过 <code>bin/&lt;arch&gt;-pc-windows-msvc-sdk.cfg</code> 与 <code>bin/&lt;arch&gt;-pc-windows-msvc-clang-cl-sdk.cfg</code> 读取它们，而这两个文件会在运行 <code>fetch</code>、<code>use</code> 和 <code>remove</code> 时改写：通过 <code>sdk/windows</code> 引入当前启用 SDK 的配置文件，或标明当前没有对应架构的 SDK（<a href="./../guide/cross-compiling#msvc-targets">原因见此</a>）。更新 conda 软件包会重置这些文件，使其不指向任何 SDK；再次运行 <code>sdk use</code> 即可重新启用。在 Linux 与 macOS 主机上，配置文件也会直接指定 <code>sdk/windows</code>。在 Linux 与 Windows 主机上，macOS 目标平台的配置文件会将 <code>sdk/macos</code> 设为 <code>-isysroot</code>（<a href="./../guide/cross-compiling#on-linux-and-windows-hosts">原因见此</a>）；而在 macOS 主机上默认使用 Xcode 的 SDK，若要使用下载的 SDK 则需手动传入 <code>-isysroot</code>。通过 <code>--sdk-dir</code> 下载的 SDK 位于工具链目录之外，工具链自带的配置文件不会自动查找它。</p><p>在 Windows 上，目录联接记录的是绝对路径。移动工具链目录后，运行 <code>xclang sdk use &lt;name&gt;</code> 可将 <code>sdk/windows</code> 或 <code>sdk/macos</code> 重新指向新位置下的 SDK。在 Windows 上默认使用目录联接下载的 macOS SDK 内部还包含大量目录联接：移动工具链目录后请重新下载，或在下载时传入 <code>--links copy</code> 以免生成任何链接。</p><h3 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h3><p>编译进程序内部的 <code>xclang/sdk-versions.json</code> 列出了厂商提供的所有版本：</p><ul><li>NuGet 上的 Windows SDK；</li><li>Visual Studio 各发布频道中的 MSVC 工具集；</li><li>Apple 软件更新目录中的 macOS SDK 安装包；</li><li>预设（preset）：GitHub runner 镜像所使用的版本，使交叉构建环境与 CI 工作流一致。其中 <code>windows-2022</code> 包含 MSVC 14.44，其 STL 仍支持 Windows 7 SP1 与 8.1。</li></ul><p>未指定版本时，默认采用预设中的版本。</p><h3 id="下载内容" tabindex="-1">下载内容 <a class="header-anchor" href="#下载内容" aria-label="Permalink to &quot;下载内容&quot;">​</a></h3><p><strong>macOS</strong> 来自 <code>swcdn.apple.com</code> 上的 Command Line Tools 安装包，无需 Apple ID。解压时会跳过 man 手册、可执行工具与 Perl 文件。在 Windows 上，符号链接会转换为无需提权的目录联接（针对目录）和硬链接（针对文件）。下载体积为 62 MB，解压后为 610 MB。</p><p><strong>Windows</strong> 来自 Visual Studio 的 <code>.vsix</code> 包与 NuGet 的 <code>Microsoft.Windows.SDK.CPP</code> 包，按 Visual Studio 安装目录的 <code>/winsysroot</code> 结构排布。<code>.vsix</code> 包提供 CRT 与 STL：包括头文件、STL 的 <code>std</code> 模块源码（<code>std.ixx</code>），以及各架构的静态与 DLL 运行时库和静态运行时库的 PDB 文件。调试构建链接时会查找这些 PDB 文件，缺失则会报 LNK4099 警告。在区分大小写的文件系统上，解压时还会创建约 3,600 个链接，兼容 Windows 代码常用的大小写拼写。同时下载 x64 与 arm64 时下载体积为 600 MB，解压后为 1.8 GB。</p><h2 id="目标平台" tabindex="-1">目标平台 <a class="header-anchor" href="#目标平台" aria-label="Permalink to &quot;目标平台&quot;">​</a></h2><p><code>xclang target list</code> 列出当前版本的目标平台，目前全部内置于工具链中。<code>xclang target add</code> 与 <code>target remove</code> 用于安装和移除以独立压缩包发布的目标平台，目前尚无版本发布此类压缩包（<a href="./../design/roadmap#target-archives">目标平台压缩包</a>）。</p><h2 id="cargo" tabindex="-1">cargo <a class="header-anchor" href="#cargo" aria-label="Permalink to &quot;cargo&quot;">​</a></h2><p><code>xclang cargo build --target &lt;Rust target&gt;</code> 及其他 cargo 子命令会在运行 cargo 时设好目标平台（由 <code>--target</code>、<code>build.target</code> 指定，或取当前主机）所需的各项环境变量。每个目标平台的链接器都是 <code>xclang</code> 自身，在缓存目录中命名为 <code>&lt;Rust target&gt;-linker</code>，负责带上目标平台所需的参数调用 clang（MSVC 目标平台则调用 lld-link）。如果目标平台缺少 Rust 标准库，会自动运行 <code>rustup target add</code> 安装；如果缺少厂商 SDK，则会提示运行对应的 <code>xclang sdk fetch</code> 命令。针对各个目标平台设置的具体变量见 <a href="./../integrations/cargo#what-xclang-cargo-sets">Rust 与 Cargo</a>。</p><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><p>所有网络请求只发送 <code>User-Agent: xclang/&lt;version&gt;</code>，不附带任何其他用户信息。TLS 由基于 ring 的 rustls 实现，证书则对照操作系统的信任库校验：macOS 上使用 Security.framework，Windows 上使用系统证书存储，Linux 上读取系统的 CA 证书文件。因此企业内部安装的根证书也会自动受信任。如果 Linux 系统未安装 CA 证书文件，则会回退使用 Mozilla 根证书列表。</p><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_ROOT</code></td><td>工具链目录，同 <code>--root</code></td></tr><tr><td><code>XCLANG_SDK_DIR</code></td><td>存放 SDK 的其他目录，同 <code>--sdk-dir</code></td></tr><tr><td><code>XCLANG_JOBS</code></td><td>解压使用的线程数，默认为每个逻辑 CPU 一个线程</td></tr><tr><td><code>XCLANG_TARGET_INDEX</code></td><td>指定其他目标平台索引，同 <code>--index</code></td></tr><tr><td><code>XCLANG_CACHE_DIR</code></td><td><code>xclang cargo</code> 存放链接器包装程序与 CMake 工具链文件的目录，默认为用户缓存目录下的 <code>xclang</code></td></tr><tr><td><code>XCLANG_STDLIB</code></td><td>设为 <code>platform</code> 时，<code>xclang cargo</code> 使用平台的 C++ 标准库编译 C++ 代码（<a href="./../integrations/cargo#the-system-s-c-library">Rust 与 Cargo</a>）</td></tr><tr><td><code>HTTPS_PROXY</code>, <code>HTTP_PROXY</code>, <code>ALL_PROXY</code>, <code>NO_PROXY</code></td><td>代理设置，均会生效</td></tr><tr><td><code>SSL_CERT_FILE</code></td><td>CA 证书文件路径，在 Linux 上读取</td></tr></tbody></table>`,26)])])}const m=d(a,[["render",s]]);export{h as __pageData,m as default};
